import random, collections, itertools, time, math
n=19
all_edges=[(i,j) for i in range(n) for j in range(i+1,n)]

def girth_ok(edges):
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    # BFS per node find shortest cycle
    g=999
    for s in range(n):
        dist=[-1]*n; par=[-1]*n; dist[s]=0; q=collections.deque([s])
        while q:
            u=q.popleft()
            for v in adj[u]:
                if dist[v]<0:
                    dist[v]=dist[u]+1; par[v]=u; q.append(v)
                elif par[u]!=v and par[v]!=u:
                    g=min(g,dist[u]+dist[v]+1)
                    if g<8:return False,g
    return True,g

def dist_without(adj,u,v,maxd=6):
    # is distance <=6?
    q=collections.deque([u]); dist={u:0}
    while q:
        x=q.popleft(); d=dist[x]
        if d>=maxd: continue
        for y in adj[x]:
            if y==v: return d+1
            if y not in dist:
                dist[y]=d+1; q.append(y)
    return None

def random_greedy(trials=1000):
    best=[]
    best_adj=None
    for t in range(trials):
        adj=[set() for _ in range(n)]; edges=[]
        candidates=all_edges[:]
        random.shuffle(candidates)
        # iteratively choose random among admissible
        while True:
            admiss=[]
            for e in all_edges:
                u,v=e
                if v not in adj[u] and dist_without(adj,u,v,6) is None:
                    admiss.append(e)
            if not admiss: break
            # bias high degree? random
            e=random.choice(admiss)
            u,v=e; adj[u].add(v); adj[v].add(u); edges.append(e)
        if len(edges)>len(best):
            best=edges[:]; best_adj=adj
            print('trial',t,'best',len(best), sorted(best), 'deg',[len(a) for a in adj], flush=True)
            ok,g=girth_ok(best); print(ok,g)
            if len(best)>=27: return best
    return best
